// Purchase data package
const purchaseData = async (networkKey, recipient, capacity, apiKey) => {
  try {
    const response = await fetch('/api/data-purchase', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': apiKey
      },
      body: JSON.stringify({
        networkKey,
        recipient,
        capacity
      })
    });

    const result = await response.json();
    if (result.success) {
      console.log('Data package purchased successfully!');
      console.log('Reference:', result.data.reference);
      console.log('Status:', result.data.status);
      return result.data;
    } else {
      console.log('Purchase failed:', result.error);
      return null;
    }
  } catch (error) {
    console.error('API request failed:', error);
    return null;
  }
};

// Check order status using GET (recommended)
const checkOrderStatus = async (reference, apiKey) => {
  try {
    const response = await fetch(`/api/external/order-status?reference=${reference}`, {
      method: 'GET',
      headers: {
        'X-API-Key': apiKey
      }
    });

    const result = await response.json();
    if (result.success) {
      console.log('Order status:', result.data.status);
      return result.data;
    } else {
      console.log('Status check failed:', result.error);
      return null;
    }
  } catch (error) {
    console.error('API request failed:', error);
    return null;
  }
};

